import{_ as r,I as n,b as s,d as o,ah as a,J as i}from"./chunks/framework.7NXsYIIo.js";const f=JSON.parse('{"title":"Node.js — runtime to backend services","description":"A Node.js runtime course with explicit backend, database and deployment continuations.","frontmatter":{"title":"Node.js — runtime to backend services","description":"A Node.js runtime course with explicit backend, database and deployment continuations.","outline":"deep"},"headers":[],"relativePath":"node-js/index.md","filePath":"node-js/index.md"}'),d={name:"node-js/index.md"};function l(c,e,h,u,p,m){const t=n("MermaidDiagram");return o(),s("div",null,[e[0]||(e[0]=a('<h1 id="node-js-runtime-to-backend-services" tabindex="-1">Node.js: runtime to backend services <a class="header-anchor" href="#node-js-runtime-to-backend-services" aria-label="Permalink to “Node.js: runtime to backend services”">​</a></h1><p><strong>Start with the runtime course.</strong> Learn how Node runs code and handles resources first. Add Express, databases, authentication and deployment later; you do not need a full-stack application to begin.</p><p>The goal is to explain the runtime, build programs with limits on input and work, diagnose common failures and clean up files, timers and connections. Some later chapters go deeper into security and reliability. Reading the material does not replace implementing and testing the exercises yourself.</p><h2 id="prerequisites-and-boundaries" tabindex="-1"><span class="hub-section-number">1 </span>Prerequisites and boundaries <a class="header-anchor" href="#prerequisites-and-boundaries" aria-label="Permalink to “1 Prerequisites and boundaries”">​</a></h2><p>Before starting, learn JavaScript functions, scope, closures, arrays, objects, modules, basic promises and <code>try</code>/<code>catch</code>. You also need basic terminal and package-manager skills. Some examples use TypeScript annotations to describe expected inputs and outputs. Read <a href="./module-01-nodejs-foundations.html#javascript-examples-and-typescript-examples">running the examples</a> before running them.</p><p>Use the <a href="./prerequisites-and-boundaries.html">shared JavaScript references</a> to fill a specific gap when needed. You do not have to repeat a whole frontend course. Node and browsers provide different environments: a Node experiment cannot by itself prove how a browser renders a page, handles cookies or enforces CORS.</p><table tabindex="0"><thead><tr><th>Scope</th><th>Includes</th><th>Does not have to come first</th></tr></thead><tbody><tr><td>Core Node.js</td><td>Modules/npm/process, async execution, errors, files, bytes/streams, raw HTTP, cancellation/cleanup, testing and runtime diagnostics</td><td>Express, ORM, database, cloud or broker</td></tr><tr><td>Backend service continuation</td><td>Express/use cases, current authorization, API schemas, application lifecycle</td><td>Microservices or multiple alternative frameworks</td></tr><tr><td>Persistence continuation</td><td>PostgreSQL/SQL/MikroORM; constraints, transactions, migrations and query diagnosis</td><td>MongoDB or Redis</td></tr><tr><td>Delivery/distribution continuation</td><td>Containers, restore/rollback, durable jobs, operational failure boundaries</td><td>AWS/Kubernetes administration or a deployed multi-service system</td></tr></tbody></table><p><span class="notes-section-label"><strong>See the course boundaries</strong></span></p><p>Follow the runtime path first. Add backend, persistence and delivery when the application needs those responsibilities.</p>',9)),i(t,{"encoded-source":"flowchart%20TD%0A%20Prereq%5B%22JavaScript%20and%20terminal%20prerequisites%22%5D%20--%3E%20Runtime%5B%22Runtime%3A%20modules%2C%20async%20work%2C%20resources%2C%20HTTP%20and%20diagnostics%22%5D%0A%20Runtime%20--%3E%20Practice%5B%22Small%20CLI%20and%20local%20HTTP%20practice%22%5D%0A%20Practice%20--%3E%20Backend%5B%22Backend%3A%20Express%2C%20contracts%20and%20authorization%22%5D%0A%20Backend%20--%3E%20Persistence%5B%22Persistence%3A%20SQL%2C%20constraints%2C%20transactions%20and%20ORM%22%5D%0A%20Persistence%20--%3E%20Delivery%5B%22Delivery%20and%20distributed%20failure%3A%20deploy%2C%20recover%20and%20coordinate%20durable%20work%22%5D"}),e[1]||(e[1]=a('<h2 id="recommended-reading-order" tabindex="-1"><span class="hub-section-number">2 </span>Recommended reading order <a class="header-anchor" href="#recommended-reading-order" aria-label="Permalink to “2 Recommended reading order”">​</a></h2><h3 id="runtime-foundations" tabindex="-1"><span class="hub-section-number">2.1 </span>Runtime foundations <a class="header-anchor" href="#runtime-foundations" aria-label="Permalink to “2.1 Runtime foundations”">​</a></h3><ul><li><a href="./module-01-nodejs-foundations.html">Foundations</a>: runtime, CJS/ESM, npm, scheduling, promises and bounded concurrency.</li><li><a href="./module-02-standard-library.html">Standard library</a>: errors, process/CLI, files/handles/paths, crypto and subprocess/worker ownership. Study worker pools and cluster in more depth later.</li><li><a href="./module-03-events-buffers-streams.html">Events, buffers and streams</a>: notifications, bytes/encoding, framing, backpressure, iteration and cleanup.</li><li><a href="./module-04-testing.html">Testing</a>: awaitable checks, useful assertions, controlled failures and open handles. Use its database and end-to-end sections when you add a service.</li><li><a href="./module-05-networking.html">Networking</a>: raw HTTP, request/response streams, bounded clients, TLS/DNS, deadlines and security boundaries. REST architecture and real-time alternatives can follow your first server.</li><li><a href="./module-11-performance-diagnostics.html">Diagnostics</a>: measure event-loop behavior, resource ownership, memory categories and one reproducible bottleneck. Database pool diagnosis belongs with persistence.</li><li><a href="./module-10-production-ready-applications.html">Lifecycle</a>: use configuration, startup, safe diagnostics, readiness and shutdown for your first long-running server. Use its deployment sections later.</li></ul><p>Apply these ideas in the <a href="./../practice/node-js/core-project.html">small log-analyzer project</a>, then practise more failure cases with <a href="./../practice/backend-project.html#p-332">P-332</a>. Use the <a href="./../practice/node-js/">chapter exercises</a> for your own implementation and checks. Reading an explanation does not complete its exercise.</p><h3 id="one-backend-and-persistence-path" tabindex="-1"><span class="hub-section-number">2.2 </span>One backend and persistence path <a class="header-anchor" href="#one-backend-and-persistence-path" aria-label="Permalink to “2.2 One backend and persistence path”">​</a></h3><ul><li><a href="./module-06-express-architecture.html">Express and architecture</a>: ordered middleware, validation, use cases and persistence boundaries.</li><li><a href="./module-08-postgresql-mikroorm.html">PostgreSQL and MikroORM</a>: learn SQL/constraints before ORM behavior. The <a href="./../workbench/node-js/database/sql-queries.html">SQL workbench</a> supplies one coherent fixture.</li><li><a href="./module-09-authentication-authorization.html">Authentication and authorization</a>: sessions, CSRF, passwords, tokens and current owner/tenant policy. Its <a href="./../workbench/node-js/backend/session-app.html">runnable application reference</a> reuses existing source.</li><li>Return to <a href="./module-10-production-ready-applications.html">production lifecycle</a> and the database sections of <a href="./module-11-performance-diagnostics.html">diagnostics</a> once those parts work together as a service.</li></ul><p><a href="./../practice/backend-project.html#p-331">P-331</a> describes how to combine these parts. Follow PostgreSQL and REST as the main path. Use <a href="./module-07-mongodb-mongoose.html">MongoDB/Mongoose</a> as an optional comparison with document storage.</p><h3 id="delivery-and-distributed-failure" tabindex="-1"><span class="hub-section-number">2.3 </span>Delivery and distributed failure <a class="header-anchor" href="#delivery-and-distributed-failure" aria-label="Permalink to “2.3 Delivery and distributed failure”">​</a></h3><ul><li><a href="./module-12-resilient-distributed-systems.html">Resilient/distributed systems</a>: unknown outcomes, duplicates, outbox, queues, caching and recovery. A modular monolith remains the starting point.</li><li><a href="./container-deployment-lab.html">Container deployment</a>, <a href="./database-recovery.html">backup/recovery</a>, <a href="./release-artifact-compatibility.html">release compatibility</a> and <a href="./full-stack-deployment.html">whole-stack local deployment</a> prepare <a href="./../practice/backend-project.html#p-333">P-333</a>. A local example passing does not prove an authenticated hosted deployment works.</li></ul><h2 id="supplements-by-requirement" tabindex="-1"><span class="hub-section-number">3 </span>Supplements by requirement <a class="header-anchor" href="#supplements-by-requirement" aria-label="Permalink to “3 Supplements by requirement”">​</a></h2><p>The sidebar groups these extra lessons into <span class="notes-section-label"><strong>Backend and persistence continuation</strong></span> (database queries and calendar data), <span class="notes-section-label"><strong>Security and data handling</strong></span> (uploads, deletion, callbacks and browser behavior), and <span class="notes-section-label"><strong>API transports and adapters</strong></span> (live updates, alternative APIs and shared caches or limits). <strong>Choose an extra lesson when your service needs it.</strong> You do not need all of them before learning the runtime.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Reading/reference</th></tr></thead><tbody><tr><td>Public API contract and drift</td><td><a href="./../workbench/node-js/backend/rest-contracts.html">REST/OpenAPI workbench</a></td></tr><tr><td>Ordered database feeds and calendar data</td><td><a href="./cursor-pagination.html">Cursor pagination</a>, <a href="./dates-and-time-zones.html">dates/time zones</a></td></tr><tr><td>Private bounded text ingress</td><td><a href="./safe-text-uploads.html">Uploads and multipart variant</a>, <a href="./retention-and-deletion.html">expiry/deletion</a></td></tr><tr><td>Provider callbacks</td><td><a href="./signed-webhooks.html">Signed webhooks</a></td></tr><tr><td>Browser document/login boundaries</td><td><a href="./browser-csp.html">CSP</a>, <a href="./oidc-and-csrf-lab.html">OIDC/CSRF alternatives</a></td></tr><tr><td>Real-time updates or alternative APIs</td><td><a href="./realtime-transports.html">SSE/polling/gRPC</a>, <a href="./graphql-basics.html">GraphQL</a></td></tr><tr><td>Shared cache/abuse limits</td><td><a href="./redis-adapters.html">Redis adapters</a></td></tr><tr><td>Durable work and schedules</td><td><a href="./jobs-and-schedules.html">Jobs/scheduling</a></td></tr><tr><td>Cloud architecture awareness</td><td><a href="./aws-service-slice.html">AWS slice</a>; Kubernetes awareness remains in the deployment continuation</td></tr></tbody></table><p>The <a href="./../workbench/node-js/">workbench home</a> labels examples you can run directly, source examples you can connect to other code, and templates that need extra setup. Find project requirements, pass criteria and checklists in <a href="./../practice/node-js/">practice</a>. Keep any Autocode task&#39;s supplied build, Jest, database and coverage settings and restricted tests unchanged. Only the user may push repository changes.</p>',13))])}const g=r(d,[["render",l]]);export{f as __pageData,g as default};
